import * as React from 'react'

import {useVisibility} from '../../../../../../common/Visible/Visible.hooks'
import type {AgentsPagesCanViewAgentDetailsFragment$key} from '../../../../__generated__/AgentsPagesCanViewAgentDetailsFragment.graphql'
import type {AgentsTreeAgentNode} from '../../../../AgentsSidebar/AgentsSidebar.types'
import AgentFetcher from '../../../AgentFetcher/AgentFetcher'
import AgentListView from '../../../AgentListView/AgentListView'
import AgentPlaceholderListView from '../../../AgentListView/AgentPlaceholderListView'

function VisibleAgent({
  className,
  dataKey,
  ...agentNode
}: AgentsTreeAgentNode & {
  className: string
  dataKey: AgentsPagesCanViewAgentDetailsFragment$key | null
}) {
  const ref = React.useRef(null)
  const isVisible = useVisibility(ref)
  return (
    <div ref={ref} className={className}>
      {isVisible ? ( // TODO: fetch agent's data only is the user has `View agent details` permission
        <AgentFetcher agentId={agentNode.id}>
          {({agent}) => {
            if (agent != null) {
              return (
                <AgentListView agent={agent} removable={agentNode.removable} dataKey={dataKey} />
              )
            }

            return <AgentPlaceholderListView {...agentNode} dataKey={dataKey} />
          }}
        </AgentFetcher>
      ) : (
        <AgentPlaceholderListView {...agentNode} dataKey={dataKey} />
      )}
    </div>
  )
}

export default VisibleAgent
