import HelpIcon from '@jetbrains/icons/help.svg'
import Button from '@jetbrains/ring-ui-built/components/button/button'
import type {PopupAttrs} from '@jetbrains/ring-ui-built/components/popup/popup'
import Tooltip from '@jetbrains/ring-ui-built/components/tooltip/tooltip'
import {SvgIcon} from '@jetbrains/teamcity-ui/dist/components'
import classNames from 'classnames'
import plur from 'plur'

import styles from './InstancesCounter.module.css'

const tooltipPopupProps: Partial<PopupAttrs> = {
  left: 18,
  directions: [Tooltip.PopupProps.Directions.BOTTOM_RIGHT, Tooltip.PopupProps.Directions.TOP_RIGHT],
}

function InstancesCounter({
  count,
  busyCount,
  className,
  cloud,
}: {
  count: number
  busyCount: number
  className?: string | null | undefined
  cloud: boolean
}) {
  return count === 0 ? (
    <span className={classNames(className, styles.couter)}>
      {'no agents running builds'}
      {cloud && (
        <Tooltip
          delay={100}
          popupProps={tooltipPopupProps}
          title={'Cloud agents are started on demand'}
        >
          <SvgIcon className={styles.helpIcon} icon={HelpIcon} />
        </Tooltip>
      )}
    </span>
  ) : (
    <Button className={classNames(className, styles.couter)} inline>
      {busyCount > 0 ? (
        <>
          <span className={styles.runningCount}>{`${busyCount} ${plur(
            'agent',
            busyCount,
          )} running ${plur('build', busyCount)}`}</span>
          {busyCount < count ? ', ' : null}
        </>
      ) : null}
      {busyCount < count ? `${count} ${plur('agent', count)} in total` : ''}
      <SvgIcon icon={'chevron-down'} />
    </Button>
  )
}

export default InstancesCounter
