import {IconButton} from '@jetbrains/teamcity-ui/dist/components'
import classNames from 'classnames'
import type {MouseEventHandler, ReactNode} from 'react'

import styles from './IndentedExpandHandle.module.css'

type IndentedContainerProps = {
  level: number
  extraIndent?: number
  className?: string
  children: ReactNode
}

const INDENT_LEVEL_UNIT = 16

export function IndentedContainer({
  level,
  extraIndent = 0,
  className,
  children,
}: IndentedContainerProps) {
  return (
    <div
      className={classNames(styles.container, className)}
      style={{paddingLeft: INDENT_LEVEL_UNIT * (level - 1) + extraIndent}}
    >
      {children}
    </div>
  )
}

type ExpandHandleProps = {
  expandable: boolean
  expanded?: boolean | null | undefined
  className?: string | undefined
  iconClassName?: string | undefined
  onClick?: MouseEventHandler
}

export function ExpandHandle({
  expandable,
  expanded,
  className,
  iconClassName,
  onClick,
}: ExpandHandleProps) {
  return expandable ? (
    <IconButton
      className={classNames(styles.icon, className)}
      iconClassName={iconClassName}
      title={expanded === true ? 'Collapse' : 'Expand'}
      icon={expanded === true ? 'chevron-down' : 'chevron-right'}
      onClick={onClick}
    />
  ) : null
}

export const EXPAND_HANDLE_WIDTH = 16

type IndentedExpandHandleProps = Omit<IndentedContainerProps, 'children' | 'extraIndent'> &
  ExpandHandleProps & {
    chevronClassName?: string | undefined
    chevronIconClassName?: string | undefined
  }

export default function IndentedExpandHandle({
  level,
  expandable,
  expanded,
  className,
  chevronClassName,
  chevronIconClassName,
}: IndentedExpandHandleProps) {
  return (
    <IndentedContainer
      className={className}
      level={level}
      extraIndent={expandable ? 0 : EXPAND_HANDLE_WIDTH}
    >
      <ExpandHandle
        expanded={expanded}
        expandable={expandable}
        className={chevronClassName}
        iconClassName={chevronIconClassName}
      />
    </IndentedContainer>
  )
}
