import closeIcon from '@jetbrains/icons/close.svg'
import LoaderInline from '@jetbrains/ring-ui-built/components/loader-inline/loader-inline'
import {Size} from '@jetbrains/ring-ui-built/components/toggle/toggle'
import {IconButton} from '@jetbrains/teamcity-ui/dist/components'
import classNames from 'classnames'
import type {MouseEventHandler} from 'react'

import {useDistanceToNow} from '../../../../../hooks/useTimeSelector'
import {getAgentHref} from '../../../../../routes'
import type {NormalizedAgent} from '../../../../../types'
import {stringifyId} from '../../../../../types'
import AgentLink from '../../../../common/AgentLink/AgentLink'
import Icon from '../../../../common/Icon/Icon'
import type {AgentsPagesCanViewAgentDetailsFragment$key} from '../../__generated__/AgentsPagesCanViewAgentDetailsFragment.graphql'
import {STRING_DEFAULT_AGENT_POOL_ID} from '../../AgentPoolPage/AgentPoolPage.consts'
import {useCanViewAgentDetails} from '../../AgentsPages.hooks'
import {EnableAgentForm} from '../EnableAgentForm/EnableAgentForm'

import {useMoveAgentToAgentPool} from './AgentListView.hooks'
import DisconnectionComment from './DisconnectionComment/DisconnectionComment'
import StatusComment from './StatusComment/StatusComment'

import styles from './AgentListView.module.css'

function AgentListView({
  agent,
  className,
  removable,
  dataKey,
}: {
  agent: NormalizedAgent
  className?: string
  removable?: boolean
  dataKey: AgentsPagesCanViewAgentDetailsFragment$key | null
}) {
  const {
    id,
    connected,
    name,
    pool,
    enabled = false,
    osType,
    disconnectionComment,
    lastActivityTime,
    typeId,
  } = agent
  const {comment: enableComment, statusSwitchTime} = agent.enabledInfo || {}
  const statusSwitchFromNow = useDistanceToNow(statusSwitchTime)
  const lastActivityFromNow = useDistanceToNow(lastActivityTime)
  const [moveAgentToDeaultPool, movingAgentToDeaultPool] = useMoveAgentToAgentPool(
    stringifyId(agent.id),
    STRING_DEFAULT_AGENT_POOL_ID,
  )
  const canViewAgentDetails = useCanViewAgentDetails(dataKey)

  return (
    <div data-test="agent" className={classNames(className, styles.agent)}>
      {connected ? (
        <EnableAgentForm
          poolId={pool.id}
          typeId={typeId}
          className={styles.toggle}
          id={id}
          name={name}
          enabled={enabled}
          authorized
          size={Size.Size20}
        />
      ) : null}
      <AgentLink
        isSakuraUI
        name={name}
        className={styles.link}
        {...(canViewAgentDetails
          ? {
              href: getAgentHref(id),
              agentId: id,
              osType,
            }
          : {})}
      />
      {connected && !('build' in agent) && <div className={styles.idle}>{'Idle'}</div>}
      {'build' in agent && agent.build == null && (
        <div className={styles.runningPlaceholder}>
          <Icon className={styles.icon} name="running_green" />
          {'Running a build. You do not have permissions to see the build details.'}
        </div>
      )}
      {connected ? null : (
        <DisconnectionComment className={styles.disconnectionComment}>
          {disconnectionComment}
        </DisconnectionComment>
      )}
      {enableComment?.text != null ? (
        <StatusComment
          statusTitle={enabled ? 'Enabled' : 'Disabled'}
          text={enableComment.text}
          user={enableComment.user}
          timestamp={enableComment.timestamp}
          className={styles.statusComment}
        />
      ) : null}
      <div className={styles.split} />
      {connected && statusSwitchFromNow != null ? (
        <div className={styles.enableTimer}>
          {`Will be ${enabled ? 'off' : 'on'} ${statusSwitchFromNow}`}
        </div>
      ) : null}
      {!connected && lastActivityFromNow != null ? (
        <div
          className={styles.lastCommunicationTimer}
        >{`Last communication ${lastActivityFromNow}`}</div>
      ) : null}
      {removable ? (
        movingAgentToDeaultPool ? (
          <LoaderInline className={styles.loader} />
        ) : (
          <IconButton
            onClick={moveAgentToDeaultPool as MouseEventHandler<HTMLButtonElement>}
            icon={closeIcon}
            className={styles.unassignButton}
            title="Move to the Default agent pool"
          />
        )
      ) : null}
    </div>
  )
}

export default AgentListView
