import closeIcon from '@jetbrains/icons/close.svg'
import LoaderInline from '@jetbrains/ring-ui-built/components/loader-inline/loader-inline'
import {IconButton} from '@jetbrains/teamcity-ui/dist/components'
import classNames from 'classnames'
import type {MouseEventHandler, MouseEvent} from 'react'
import {useCallback} from 'react'

import {getAgentTypeHref} from '../../../../../routes'
import {stringifyId} from '../../../../../types'
import AgentLink from '../../../../common/AgentLink/AgentLink'
import type {AgentsPagesCanViewAgentDetailsFragment$key} from '../../__generated__/AgentsPagesCanViewAgentDetailsFragment.graphql'
import {STRING_DEFAULT_AGENT_POOL_ID} from '../../AgentPoolPage/AgentPoolPage.consts'
import {ExpandHandle} from '../../AgentPoolPage/IndentedExpandHandle/IndentedExpandHandle'
import {useCanViewAgentDetails} from '../../AgentsPages.hooks'
import type {AgentsTreeAgentTypeNode} from '../../AgentsSidebar/AgentsSidebar.types'

import {useMoveCloudImageToAgentPool} from './AgentListView.hooks'
import CloudAgentIcon from './CloudAgentIcon/CloudAgentIcon'
import InstancesCounter from './InstancesCounter/InstancesCounter'
import InstancesDropdown from './InstancesDropdown/InstancesDropdown'

import styles from './AgentListView.module.css'

type Props = AgentsTreeAgentTypeNode & {
  className?: string | null | undefined
  expandable?: boolean
  expanded?: boolean
  onClick?: MouseEventHandler
  removable?: boolean
  dataKey: AgentsPagesCanViewAgentDetailsFragment$key | null
}

const ANCHOR_CLASSNAME = 'dropdown-anchor'

export default function CloudAgentListView({
  id,
  title,
  osType,
  count,
  busyCount,
  children,
  className,
  expandable,
  expanded,
  onClick,
  removable,
  dataKey,
}: Props) {
  const counter = (
    <InstancesCounter
      count={count}
      busyCount={busyCount}
      className={expandable ? ANCHOR_CLASSNAME : null}
      cloud
    />
  )
  const onToggleExpand = useCallback(
    (e: MouseEvent) => {
      if (onClick != null && (e.target as Element)?.closest(`.${ANCHOR_CLASSNAME}`) == null) {
        onClick(e)
      }
    },
    [onClick],
  )
  const [moveCloudImageToDeaultPool, movingCloudImageToDeaultPool] = useMoveCloudImageToAgentPool(
    stringifyId(id),
    STRING_DEFAULT_AGENT_POOL_ID,
  )
  const canViewAgentDetails = useCanViewAgentDetails(dataKey)
  const agentTypeHref = canViewAgentDetails ? getAgentTypeHref(id) : null

  return (
    <div
      className={classNames(className, styles.agent, {[styles.expandable]: expandable})}
      onClick={onToggleExpand}
      role="presentation"
    >
      {expandable ? (
        <ExpandHandle expandable expanded={expanded} className={styles.expandHandle} />
      ) : null}
      <AgentLink
        isSakuraUI
        className={styles.link}
        iconClassName={styles.iconDoubleMargin}
        name={title}
        {...(canViewAgentDetails
          ? {
              href: agentTypeHref,
              typeId: id,
              osType,
            }
          : {})}
        beforeIcon={<CloudAgentIcon />}
      />
      {count > 0 ? (
        <InstancesDropdown
          instances={children}
          agentTypeId={id}
          anchor={counter}
          dataKey={dataKey}
        />
      ) : (
        counter
      )}
      <div className={styles.split} />
      {removable ? (
        movingCloudImageToDeaultPool ? (
          <LoaderInline className={styles.loader} />
        ) : (
          <IconButton
            onClick={moveCloudImageToDeaultPool as MouseEventHandler<HTMLButtonElement>}
            icon={closeIcon}
            className={styles.unassignButton}
            title="Move to the Default agent pool"
          />
        )
      ) : null}
    </div>
  )
}
