import type {DropdownProps} from '@jetbrains/ring-ui-built/components/dropdown/dropdown'
import Dropdown from '@jetbrains/ring-ui-built/components/dropdown/dropdown'
import Link from '@jetbrains/ring-ui-built/components/link/link'
import Popup from '@jetbrains/ring-ui-built/components/popup/popup'
import classNames from 'classnames'
import type * as React from 'react'

import {getAgentHref, getBuildHref, getAgentTypeHref} from '../../../../../../routes'
import type {AgentTypeId} from '../../../../../../types'
import Icon from '../../../../../common/Icon/Icon'
import RouterLinkWrapper from '../../../../../common/RouterLinkWrapper/RouterLinkWrapper'
import type {AgentsPagesCanViewAgentDetailsFragment$key} from '../../../__generated__/AgentsPagesCanViewAgentDetailsFragment.graphql'
import {useCanViewAgentDetails} from '../../../AgentsPages.hooks'
import type {
  AgentsTreeAgentNode,
  AgentsTreeCloudImageNode,
} from '../../../AgentsSidebar/AgentsSidebar.types'

import styles from './InstancesDropdown.module.css'

type Props = {
  instances: AgentsTreeCloudImageNode['children']
  agentTypeId: AgentTypeId
  anchor: DropdownProps['anchor']
  dataKey: AgentsPagesCanViewAgentDetailsFragment$key | null
}

const POPUP_DIRECTIONS = [
  Popup.PopupProps.Directions.BOTTOM_RIGHT,
  Popup.PopupProps.Directions.TOP_RIGHT,
]

function InstancesDropdownLink({
  href,
  title,
  children,
  className,
}: {
  children: React.ReactNode | string | undefined
  className?: string | undefined
  title?: string
  href?: string
}) {
  return href ? (
    <RouterLinkWrapper>
      <Link className={classNames(styles.link, className)} href={href} title={title}>
        {children}
      </Link>
    </RouterLinkWrapper>
  ) : (
    <span className={classNames(styles.link, styles.inactiveLink, className)}>{children}</span>
  )
}

type ItemProps = AgentsTreeAgentNode & {
  dataKey: AgentsPagesCanViewAgentDetailsFragment$key | null
}
function InstancesDropdownItem(props: ItemProps) {
  const canViewAgentDetails = useCanViewAgentDetails(props.dataKey)
  return (
    <div className={styles.item}>
      <InstancesDropdownLink
        title={props.name}
        {...(canViewAgentDetails ? {href: getAgentHref(props.id)} : {})}
      >
        {props.title}
      </InstancesDropdownLink>
      {!props.connected ? (
        <div className={styles.disconnectedStatus}>{'Disconnected'}</div>
      ) : !props.enabled ? (
        <div className={styles.disabledStatus}>{'Maintenance'}</div>
      ) : props.busy ? (
        <div className={styles.runningStatus}>
          <Icon className={styles.icon} name="running_green" />
          {props.buildId != null ? (
            <InstancesDropdownLink href={getBuildHref(props.buildId)}>
              {'Running'}
            </InstancesDropdownLink>
          ) : (
            'Running'
          )}
        </div>
      ) : (
        <div className={styles.idleStatus}>{'Idle'}</div>
      )}
    </div>
  )
}

const VISIBLE_INSTANCES_COUNT = 5

function InstancesDropdown({instances, agentTypeId, dataKey, ...dropdownProps}: Props) {
  const canViewAgentDetails = useCanViewAgentDetails(dataKey)
  return (
    <Dropdown {...dropdownProps} className={styles.instancesDropdown}>
      <Popup directions={POPUP_DIRECTIONS} className={styles.popup}>
        {instances.slice(0, VISIBLE_INSTANCES_COUNT).map(instance => (
          <InstancesDropdownItem key={instance.id} {...instance} dataKey={dataKey} />
        ))}
        {instances.length > VISIBLE_INSTANCES_COUNT ? (
          canViewAgentDetails ? (
            <InstancesDropdownLink
              href={getAgentTypeHref(agentTypeId)}
              className={styles.viewAllLink}
            >{`View all ${instances.length} instances`}</InstancesDropdownLink>
          ) : (
            <InstancesDropdownLink>{`${instances.length} instances in total`}</InstancesDropdownLink>
          )
        ) : null}
      </Popup>
    </Dropdown>
  )
}

export default InstancesDropdown
