import {Size} from '@jetbrains/ring-ui-built/components/toggle/toggle'
import classNames from 'classnames'

import {getAgentHref} from '../../../../../routes'
import {noop} from '../../../../../utils/empty'
import AgentLink from '../../../../common/AgentLink/AgentLink'
import type {AgentsPagesCanViewAgentDetailsFragment$key} from '../../__generated__/AgentsPagesCanViewAgentDetailsFragment.graphql'
import {useCanViewAgentDetails} from '../../AgentsPages.hooks'
import type {AgentsTreeAgentNode} from '../../AgentsSidebar/AgentsSidebar.types'
import EnableToggle from '../EnableAgentForm/EnableToggle/EnableToggle'

import DisconnectionComment from './DisconnectionComment/DisconnectionComment'

import styles from './AgentListView.module.css'

// The purpose of this component is to render a placeholder based on agent preview data
// until the full data has been loaded.
function AgentPlaceholderListView({
  className,
  dataKey,
  ...agentNode
}: AgentsTreeAgentNode & {
  className?: string
  dataKey: AgentsPagesCanViewAgentDetailsFragment$key | null
}) {
  const {id, connected, name, osType, enabled, busy} = agentNode
  const canViewAgentDetails = useCanViewAgentDetails(dataKey)

  return (
    <div className={classNames(className, styles.agent, styles.loading)}>
      {connected ? ( // This is a fake toggle that does nothing.
        <EnableToggle
          className={classNames(styles.toggle, styles.loadingToggle)}
          isToggleable={false}
          enabled={enabled}
          handleToggleClick={noop}
          title="Loading agent data..."
          size={Size.Size20}
        />
      ) : null}
      <AgentLink
        isSakuraUI
        name={name}
        className={styles.link}
        {...(canViewAgentDetails
          ? {
              href: getAgentHref(id),
              agentId: id,
              osType,
            }
          : {})}
      />
      {connected && !busy && <div className={styles.idle}>{'Idle'}</div>}
      {!connected && <DisconnectionComment className={styles.disconnectionComment} />}
      <div className={styles.split} />
    </div>
  )
}

export default AgentPlaceholderListView
